// LauncherCore's checks, the same as launcher/desktop/tests/core_test.cpp's: `swift test`.
import XCTest
@testable import LauncherCore

final class CoreTests: XCTestCase {
    func testParseConfig() {
        let text = """
            // generated by OpenMoHAA, do not modify
            unbindall
            bind TAB "+scores"
            seta name "Some Body"\r
            seta cg_crosshair_length "5"
            SETA CG_Crosshair_Color "#00ff00" // green
            set r_mode -1; seta r_customwidth "2560"; seta r_customheight 1440
            seta password "a;b//c"
            /* seta r_fullscreen "0" */ seta r_noborder "1"
            seta empty ""
            seta unterminated "abc
            seta spaced one two
            seta ünïcode "ä"

            """
        let c = parseConfig(text)
        XCTAssertEqual(c["name"], "Some Body")
        XCTAssertEqual(c["cg_crosshair_length"], "5")
        XCTAssertEqual(c["cg_crosshair_color"], "#00ff00")
        XCTAssertEqual(c["r_mode"], "-1")
        XCTAssertEqual(c["r_customwidth"], "2560")
        XCTAssertEqual(c["r_customheight"], "1440")
        XCTAssertEqual(c["password"], "a;b//c")
        XCTAssertNil(c["r_fullscreen"])
        XCTAssertEqual(c["r_noborder"], "1")
        XCTAssertEqual(c["empty"], "")
        XCTAssertEqual(c["unterminated"], "abc")
        XCTAssertEqual(c["spaced"], "one two")
        XCTAssertEqual(c["ünïcode"], "ä")
        XCTAssertNil(c["tab"])
    }

    func testEdits() {
        var e = CvarEdits(defaults: [("name", ""), ("cg_crosshair_length", "4"), ("r_fullscreen", "1")])
        XCTAssertEqual(e.get("cg_crosshair_length"), "4")
        XCTAssertTrue(e.changes.isEmpty)

        e.load(["name": "Player", "cg_crosshair_length": "6"])
        XCTAssertEqual(e.get("name"), "Player")
        XCTAssertEqual(e.get("cg_crosshair_length"), "6")
        XCTAssertEqual(e.get("r_fullscreen"), "1")
        XCTAssertTrue(e.changes.isEmpty)

        e.set("cg_crosshair_length", "8")
        XCTAssertTrue(e.changed("cg_crosshair_length"))
        // a change made in the game to another setting comes in; the launcher's own change stays
        e.load(["name": "Renamed", "cg_crosshair_length": "7"])
        XCTAssertEqual(e.get("name"), "Renamed")
        XCTAssertEqual(e.get("cg_crosshair_length"), "8")
        XCTAssertEqual(e.changes.map { $0.0 }, ["cg_crosshair_length"])
        XCTAssertEqual(e.changes.map { $0.1 }, ["8"])

        e.set("cg_crosshair_length", "7")
        XCTAssertTrue(e.changes.isEmpty)

        e.set("r_fullscreen", "0")
        e.applied()
        XCTAssertTrue(e.changes.isEmpty)
        e.load(["r_fullscreen": "0"])
        XCTAssertEqual(e.get("r_fullscreen"), "0")
        XCTAssertFalse(e.changed("r_fullscreen"))
    }

    func testArgs() {
        XCTAssertEqual(engineArg("plain"), "plain")
        XCTAssertEqual(engineArg("with space"), "with space")
        XCTAssertEqual(engineArg("a;b"), "\"a;b\"")
        XCTAssertEqual(engineArg("a+b"), "\"a+b\"")
        XCTAssertEqual(engineArg("http://x"), "\"http://x\"")
        XCTAssertEqual(engineArg("say \"hi\""), "say hi")
        XCTAssertEqual(engineArg(""), "\"\"")
        XCTAssertEqual(engineArg("tab\there"), "tab here")
        XCTAssertEqual(engineArg("ünïcode"), "ünïcode")

        var l = Launch()
        l.game = .spearhead
        l.cvars = [("name", "A B"), ("cg_crosshair_color", "00FF00")]
        l.password = "pw;1"
        l.rcon = "r"
        l.address = "1.2.3.4:12203"
        XCTAssertEqual(buildArgs(l), [
            "+set", "com_target_game", "1", "+set", "name", "A B", "+set", "cg_crosshair_color", "00FF00",
            "+set", "password", "\"pw;1\"", "+set", "rconPassword", "r", "+connect", "1.2.3.4:12203",
        ])
        XCTAssertEqual(buildArgs(Launch()), ["+set", "com_target_game", "0"])
        var elsewhere = Launch()
        elsewhere.homepath = "/games/MOH AA"
        elsewhere.basepath = "/games/MOH AA"
        XCTAssertEqual(buildArgs(elsewhere), ["+set", "fs_homepath", "/games/MOH AA", "+set", "fs_basepath",
                                              "/games/MOH AA", "+set", "com_target_game", "0"])
    }

    /// CG_UpdateCrosshair's layout (CS2's static cross) as the pixels it fills at 1920x1080, the middle one 960, 540
    func testCrosshair() {
        func shape(_ length: Double, _ gap: Double, _ thickness: Double, _ outline: Int, _ dot: Bool, _ t: Bool) -> CrossLayout {
            crosshairBoxes(Crosshair(length: length, gap: gap, thickness: thickness, outline: outline, dot: dot, t: t))
        }
        struct P: Hashable { let x, y: Int }
        // the screen's pixels the boxes fill, each once
        func screen(_ boxes: [Box]) -> Set<P> {
            var filled = Set<P>()
            for r in boxes {
                for x in r.x..<(r.x + r.w) {
                    for y in r.y..<(r.y + r.h) {
                        XCTAssertTrue(filled.insert(P(x: 960 + x, y: 540 + y)).inserted, "\(x), \(y) twice")
                    }
                }
            }
            return filled
        }
        // columns x0 to x1 by rows y0 to y1
        func pixels(_ rects: [(Int, Int, Int, Int)]) -> Set<P> {
            Set(rects.flatMap { x0, x1, y0, y1 in (x0...x1).flatMap { x in (y0...y1).map { P(x: x, y: $0) } } })
        }

        // the default: arms at x 948-955 and 964-971 (rows 539-540), y 528-535 and 544-551 (columns 959-960)
        var c = shape(8, 4, 2, 0, false, false)
        let arms = pixels([(948, 955, 539, 540), (964, 971, 539, 540), (959, 960, 528, 535), (959, 960, 544, 551)])
        XCTAssertEqual(screen(c.boxes), arms)
        XCTAssertTrue(c.outline.isEmpty)
        XCTAssertEqual([c.extent, c.start], [24, -12])
        // full outline: a pixel round each piece, not scaled
        c = shape(8, 4, 2, 1, false, false)
        let around = pixels([(947, 956, 538, 541), (963, 972, 538, 541), (958, 961, 527, 536), (958, 961, 543, 552)])
        XCTAssertEqual(screen(c.outline), around.subtracting(arms))
        XCTAssertEqual([c.extent, c.start], [26, -13])

        // thickness 1: the line on the pixel before the middle, the gap a pixel less after it
        c = shape(8, 4, 1, 0, false, false)
        XCTAssertEqual(screen(c.boxes),
                       pixels([(948, 955, 539, 539), (963, 970, 539, 539), (959, 959, 528, 535), (959, 959, 543, 550)]))
        XCTAssertEqual([c.extent, c.start], [23, -12])

        // length 1, gap 2, thickness 8, half outline, as in a CS2 screenshot; the outline above and left of each piece,
        // nowhere under one: the game's boxes, in its order
        c = shape(1, 2, 8, 2, false, false)
        let want = pixels([(957, 957, 536, 543), (962, 962, 536, 543), (956, 963, 537, 537), (956, 963, 542, 542)])
        XCTAssertEqual(screen(c.boxes), want)
        let outline = [
            (956, 535, 2, 1), (961, 535, 2, 1), (955, 536, 2, 1), (958, 536, 4, 1), (963, 536, 1, 1),
            (955, 537, 1, 1), (956, 538, 1, 3), (961, 538, 1, 3), (955, 541, 2, 1), (958, 541, 4, 1),
            (963, 541, 1, 1), (955, 542, 1, 1), (956, 543, 1, 1), (961, 543, 1, 1),
        ].map { Box(x: $0.0 - 960, y: $0.1 - 540, w: $0.2, h: $0.3) }
        XCTAssertEqual(c.outline, outline)
        XCTAssertTrue(screen(c.outline).isDisjoint(with: want))

        // gap 0: the arms meet; the dot over them, each pixel once; T-style: no top arm
        c = shape(5, 0, 2, 0, true, true)
        XCTAssertEqual(screen(c.boxes), pixels([(955, 964, 539, 540), (959, 960, 541, 544)]))
        // length 0: the dot alone, the middle t by t; thickness 0: nothing
        c = shape(0, 4, 4, 0, true, false)
        XCTAssertEqual(screen(c.boxes), pixels([(958, 961, 538, 541)]))
        XCTAssertTrue(shape(8, 4, 0, 1, true, false).boxes.isEmpty)

        // half away from zero, at least 1 above 0, 4096 at most; a negative gap (or NaN) draws as 0; outline 0 to 2
        c = shape(0.2, -3, 2.5, 7, false, false)
        XCTAssertEqual(screen(c.boxes), pixels([(959, 959, 538, 540), (958, 960, 539, 539)]))
        XCTAssertFalse(c.outline.isEmpty)
        c = shape(5000, .nan, 1, -1, false, false)
        XCTAssertEqual(c.boxes[1], Box(x: -4096, y: -1, w: 8191, h: 1))
        XCTAssertTrue(c.outline.isEmpty)
    }

    /// The game's own test codes (code/client/tests/test_crosshair.c on the vulkan branches)
    func testCrosshairCode() throws {
        func get(_ text: String) -> [String: String]? {
            guard case .success(let values) = crosshairImport(text) else { return nil }
            return Dictionary(values, uniquingKeysWith: { a, _ in a })
        }
        // red, dot, at 768 lines: sizes at 1080 lines as the game writes them
        var v = try XCTUnwrap(get("CSvbPubOq37zTGqtsPTP5QTrp5CB4xFXiKRLfzJsm49ZRe"))
        let want = ["length": "7.03125", "gap": "0", "thickness": "1.40625", "color": "FF0000", "alpha": "255",
                    "outline": "0", "outline_color": "000000", "outline_alpha": "255", "dot": "1", "t": "0"]
        for (name, value) in want {
            XCTAssertEqual(v["cg_crosshair_\(name)"], value, name)
        }
        XCTAssertEqual(v["cg_crosshair_code"], "CSvbPubOq37zTGqtsPTP5QTrp5CB4xFXiKRLfzJsm49ZRe")
        XCTAssertEqual(v.count, 11)
        // the first word, as copied with spaces or a line break around it
        v = try XCTUnwrap(get(" CSHt3ObzKS3ikGJLRBVrKjPUrhOCikyke53na8cJFtNZKa\r\n"))
        XCTAssertEqual(v["cg_crosshair_code"], "CSHt3ObzKS3ikGJLRBVrKjPUrhOCikyke53na8cJFtNZKa")
        v = try XCTUnwrap(get("CSHt3ObzKS3ikGJLRBVrKjPUrhOCikyke53na8cJFtNZKa\rx"))
        XCTAssertEqual(v["cg_crosshair_code"], "CSHt3ObzKS3ikGJLRBVrKjPUrhOCikyke53na8cJFtNZKa")
        // Dot Only: no arms, the dot
        v = try XCTUnwrap(get("CSUyBmKsvnUffbDXZTmd9GxnFxzmKaO6VAvnEphKt6jQfJ"))
        XCTAssertEqual([v["cg_crosshair_length"], v["cg_crosshair_dot"]], ["0", "1"])
        // height 100 (240 then), gap -32768, thickness 63, outline 3
        v = try XCTUnwrap(get("CS7uw3wMkJBJ4rMDLEaYbyfTJFFPvkLAhOmBFi8zOM6H2d"))
        XCTAssertEqual(["gap", "thickness", "outline"].map { v["cg_crosshair_\($0)"] }, ["-147456", "283.5", "3"])

        let rejected = [
            ("CSkSCHQKunGr2yPsJr2U3RTd8ycMA2pEs9jWnxK5KjMmWL", "garbled"),
            ("CSoQhciXBHZUKAbfexZBeMWFKxkrXL5MLumDLj3JYW4snP", "no screen height"),
            ("CSuZhVyU8icUwjTjopBSVi6ctEbq5GiOXJBRdC6LNLKaFL", "version 2"),
            ("CSGO-9JzcN-4dZtA-DdXis-8qz5T-rCnkP", "old CSGO"),
            ("CSvbPubOq37zTGqtsPTP5QTrp5CB4xFXiKRLfzJsm49ZR0", "never writes"),
            ("CSvbPubOq37zTGqtsPTP5QTrp5CB4xFXiKRLfzJsm49ZR", "44 letters"),
            ("CS99999999999999999999999999999999999999999999", "typo?"),
            (" \r\n", "no code"),
        ]
        for (code, why) in rejected {
            guard case .failure(let error) = crosshairImport(code) else {
                XCTFail(code)
                continue
            }
            XCTAssertTrue(error.reason.contains(why), "\(code): \(error.reason)")
        }
    }

    func testMisc() {
        XCTAssertEqual(trimmed("  1.2.3.4:12203 \t"), "1.2.3.4:12203")
        XCTAssertTrue(sameAddress("Host.Example", "host.example:12203"))
        XCTAssertFalse(sameAddress("host:12204", "host"))
        XCTAssertEqual(parseColor("#00ff7F"), 0x00FF7F)
        XCTAssertNil(parseColor("12345"))
        XCTAssertNil(parseColor("GGGGGG"))
        XCTAssertEqual(colorHex(0x0A0B0C), "0A0B0C")

        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "1", borderlessWindow: "0"), .space)
        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "0", borderlessWindow: "1"), .exclusive)
        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "1", borderlessWindow: "1"), .borderlessFullscreen)
        XCTAssertEqual(DisplayMode(fullscreen: "0", noborder: "0", borderlessWindow: "0"), .window)
        XCTAssertEqual(DisplayMode(fullscreen: "0", noborder: "1", borderlessWindow: "0"), .borderlessWindow)
        var e = CvarEdits(defaults: [("r_fullscreen", "1"), ("r_noborder", "0"), ("r_borderlessWindow", "0")])
        DisplayMode.borderlessFullscreen.apply(to: &e)
        XCTAssertEqual(DisplayMode(fullscreen: e.get("r_fullscreen"), noborder: e.get("r_noborder"),
                                   borderlessWindow: e.get("r_borderlessWindow")), .borderlessFullscreen)
        DisplayMode.space.apply(to: &e)
        XCTAssertEqual(e.get("r_borderlessWindow"), "0")

        // a 1080p screen: the common sizes up to its own, nothing larger, none of the display's odd modes
        let list = resolutionList(desktop: Resolution(1920, 1080))
        XCTAssertEqual(list, [(1920, 1080), (1680, 1050), (1600, 900), (1440, 1080), (1440, 900), (1366, 768),
                              (1280, 1024), (1280, 960), (1280, 720), (1152, 864), (1024, 768), (960, 720),
                              (800, 600), (640, 480)].map { Resolution($0.0, $0.1) })
        // QHD and 4K where the screen is that large; a screen's own odd size first (a MacBook's, in points)
        XCTAssertTrue(resolutionList(desktop: Resolution(2560, 1440)).contains(Resolution(2560, 1440)))
        XCTAssertFalse(resolutionList(desktop: Resolution(2560, 1440)).contains(Resolution(3840, 2160)))
        XCTAssertTrue(resolutionList(desktop: Resolution(3840, 2160)).contains(Resolution(3840, 2160)))
        XCTAssertEqual(resolutionList(desktop: Resolution(1512, 982)).first, Resolution(1512, 982))
        XCTAssertFalse(resolutionList(desktop: Resolution(1366, 768)).contains(Resolution(1440, 1080)))
        // an unknown screen: every common size
        XCTAssertEqual(resolutionList(desktop: Resolution(0, 0)), commonResolutions)

        // below 640 x 480: 640 x 480, passed as a change
        func raised(_ config: Cvars) -> CvarEdits {
            var e = CvarEdits(defaults: [("r_mode", "-2"), ("r_customwidth", "1600"), ("r_customheight", "1024")])
            e.load(config)
            raiseSmallResolution(&e)
            return e
        }
        var small = raised(["r_mode": "1"])
        XCTAssertEqual([small.get("r_mode"), small.get("r_customwidth"), small.get("r_customheight")], ["-1", "640", "480"])
        XCTAssertEqual(small.changes.count, 3)
        XCTAssertTrue(raised(["r_mode": "11"]).changes.isEmpty)
        XCTAssertTrue(raised(["r_mode": "-2"]).changes.isEmpty)
        small = raised(["r_mode": "-1", "r_customwidth": "320", "r_customheight": "200"])
        XCTAssertEqual([small.get("r_customwidth"), small.get("r_customheight")], ["640", "480"])

        XCTAssertEqual(aspectRatio(1920, 1080), "16:9")
        XCTAssertEqual(aspectRatio(1366, 768), "16:9")
        XCTAssertEqual(aspectRatio(856, 480), "16:9")
        XCTAssertEqual(aspectRatio(1920, 1200), "16:10")
        XCTAssertEqual(aspectRatio(1280, 1024), "5:4")
        XCTAssertEqual(aspectRatio(1024, 768), "4:3")
        XCTAssertEqual(aspectRatio(3440, 1440), "21:9")
        XCTAssertEqual(aspectRatio(5120, 1440), "32:9")
        XCTAssertEqual(aspectRatio(1000, 1000), "1:1")

        // r_fullscreenStretch as the game reads it, and written back as the number it means
        XCTAssertEqual(FullscreenScaling(cvar: "0"), .fit)
        XCTAssertEqual(FullscreenScaling(cvar: ""), .fit)
        XCTAssertEqual(FullscreenScaling(cvar: "1"), .stretch)
        XCTAssertEqual(FullscreenScaling(cvar: "3"), .stretch)
        XCTAssertEqual(FullscreenScaling(cvar: "2"), .oneToOne)
        var scalingEdits = CvarEdits(defaults: [("r_fullscreenStretch", "0")])
        for scaling in FullscreenScaling.allCases {
            scaling.apply(to: &scalingEdits)
            XCTAssertEqual(FullscreenScaling(cvar: scalingEdits.get("r_fullscreenStretch")), scaling)
        }

        // every size but the screen's own has something to scale
        let screen = Resolution(1920, 1080)
        XCTAssertTrue(scalingMatters(Resolution(800, 600), desktop: screen))
        XCTAssertTrue(scalingMatters(Resolution(1280, 720), desktop: screen))
        XCTAssertFalse(scalingMatters(Resolution(1920, 1080), desktop: screen))
        XCTAssertTrue(scalingMatters(Resolution(1920, 1080), desktop: Resolution(0, 0)))
    }

    func testSettingsAndServers() throws {
        // the Windows and Linux launcher's mohlauncher.json reads the same
        let json = #"{"game": 1, "slots": [{"address": "a:1", "servers": [{"label": "", "address": "a:1"}, {"address": " "}]}]}"#
        // Close on start: off unless turned on, kept as closeOnStart (the Windows and Linux launcher's name too)
        XCTAssertFalse(LauncherSettings.from(json: json.data(using: .utf8)).closeOnStart)
        XCTAssertTrue(LauncherSettings.from(json: #"{"closeOnStart": true}"#.data(using: .utf8)).closeOnStart)
        let saved = String(decoding: try JSONEncoder().encode(LauncherSettings()), as: UTF8.self)
        XCTAssertTrue(saved.contains("\"closeOnStart\":false"))
        var s = LauncherSettings.from(json: json.data(using: .utf8))
        XCTAssertEqual(s.game, .spearhead)
        XCTAssertEqual(s.slots.count, 3)
        XCTAssertEqual(s.slots[0].servers.map { $0.label }, ["a:1"])
        XCTAssertEqual(LauncherSettings.from(json: Data("not json".utf8)).slots.count, 3)

        s.remember(.alliedAssault, address: "host", password: "pw", rcon: "")
        s.remember(.alliedAssault, address: "HOST:12203", password: "pw2", rcon: "r")
        XCTAssertEqual(s.slots[0].servers.count, 2)
        XCTAssertEqual(s.slots[0].servers[1].password, "pw2")
        let encoded = String(decoding: try JSONEncoder().encode(s), as: UTF8.self)
        XCTAssertTrue(encoded.contains("\"label\""))
        XCTAssertFalse(encoded.contains("\"name\"")) // a server has a label; the player's name is the game's

        var list = listedServers(s, .alliedAssault)
        XCTAssertTrue(list[0].builtin)
        XCTAssertEqual(list[0].server.label, "Forte FFA")
        XCTAssertEqual(list.count, 3)
        s.remember(.alliedAssault, address: "151.80.234.90:12203", password: "x", rcon: "")
        list = listedServers(s, .alliedAssault)
        XCTAssertEqual(list.count, 3)
        XCTAssertEqual(list[0].server.password, "x")
        XCTAssertTrue(listedServers(s, .spearhead).isEmpty)
    }

    func testGameData() throws {
        let fm = FileManager.default
        let root = fm.temporaryDirectory.appendingPathComponent("mohl-data-test-\(UUID().uuidString)")
        defer { try? fm.removeItem(at: root) }
        try fm.createDirectory(at: root.appendingPathComponent("MAIN"), withIntermediateDirectories: true)
        XCTAssertFalse(hasGameData(root))
        try Data().write(to: root.appendingPathComponent("MAIN/pak0.PK3"))
        XCTAssertTrue(hasGameData(root))
        XCTAssertNotNil(dataFolder(root, "main"))
        XCTAssertNil(dataFolder(root, "mainta"))
    }

    func testFindConfig() throws {
        let fm = FileManager.default
        let root = fm.temporaryDirectory.appendingPathComponent("mohl-core-test-\(UUID().uuidString)")
        defer { try? fm.removeItem(at: root) }
        let home = root.appendingPathComponent("home"), base = root.appendingPathComponent("base")
        func write(_ url: URL, _ text: String) throws {
            try fm.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try text.write(to: url, atomically: true, encoding: .utf8)
        }
        let aa = home.appendingPathComponent("main/configs/omconfig.cfg")
        try write(aa, "seta name a\n")
        try write(base.appendingPathComponent("maintt/configs/unnamedsoldier.cfg"), "seta name b\n")

        XCTAssertEqual(findConfig(homes: [home, base], game: .alliedAssault)?.path, aa.path)
        XCTAssertEqual(findConfig(homes: [home, base], game: .spearhead)?.path, aa.path)
        XCTAssertEqual(findConfig(homes: [home, base], game: .breakthrough)?.path, aa.path)
        let bt = home.appendingPathComponent("maintt/configs/omconfig.cfg")
        try write(bt, "seta name c\n")
        XCTAssertEqual(findConfig(homes: [home, base], game: .breakthrough)?.path, bt.path)
        XCTAssertNil(findConfig(homes: [root.appendingPathComponent("none")], game: .alliedAssault))
        XCTAssertEqual(readConfig(bt)?["name"], "c")
    }
}
